import {createChatOrchestrator, TOOL_BUDGET_EXHAUSTED} from './chatOrchestrator.js';
import type {OrchestratorHooks, ToolBudgetInfo} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {setLogger} from '../shared/logger.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

// Counts are the contract: how many provider calls a turn makes, and how many tool rounds it actually executes.

const ASK_FOR_TOOL: MessageChunk[] = [
  {type: 'tool_use', toolCall: {id: 'c', name: 'lookup', input: {}}},
  {type: 'stop', stopReason: 'tool_use'},
];
const FINISH: MessageChunk[] = [
  {type: 'text', text: 'Done.'},
  {type: 'stop', stopReason: 'end_turn'},
];
const alwaysTools = (): MessageChunk[] => ASK_FOR_TOOL;
const toolThenFinish = (call: number): MessageChunk[] => (call === 0 ? ASK_FOR_TOOL : FINISH);

const budgetEngine = (
  maxToolRounds?: number,
  script: (call: number) => MessageChunk[] = alwaysTools,
  hooks: OrchestratorHooks = {}
) => {
  const counts = {providerCalls: 0, executions: 0};
  const provider: AIProvider = {
    async *sendMessage() {
      yield* script(counts.providerCalls++);
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const registry = new ToolRegistry();
  registry.register({name: 'lookup', description: 'Looks something up.', inputSchema: {type: 'object'}}, async () => {
    counts.executions++;
    return 'found';
  });
  const options = maxToolRounds === undefined ? {hooks} : {maxToolRounds, hooks};
  const orchestrator = createChatOrchestrator(
    provider,
    new PromptBuilder({identity: 'Budget test.'}),
    registry,
    options
  );
  const session: ChatSession = {sessionId: 's', userId: 'u', entries: [{role: 'user', content: 'go', timestamp: 't'}]};
  return {orchestrator, counts, session};
};

const budgetRun = async (...args: Parameters<typeof budgetEngine>) => {
  const {orchestrator, counts, session} = budgetEngine(...args);
  const chunks: MessageChunk[] = [];
  for await (const chunk of orchestrator.processMessageStream(session)) chunks.push(chunk);
  return {...counts, chunks};
};

const BUDGET_STOP: MessageChunk = {type: 'stop', stopReason: TOOL_BUDGET_EXHAUSTED};
const SENTENCE = 'I could not finish looking that up, so a colleague will follow up.';
const USAGE: UsageMetadata = {inputTokens: 7, outputTokens: 3, totalTokens: 10};
const twoTools = (): MessageChunk[] => [
  {type: 'tool_use', toolCall: {id: 'c1', name: 'lookup', input: {}}},
  {type: 'tool_use', toolCall: {id: 'c2', name: 'notify', input: {}}},
  {type: 'stop', stopReason: 'tool_use'},
];
const toolsWithUsage = (): MessageChunk[] => [ASK_FOR_TOOL[0], {type: 'stop', stopReason: 'tool_use', usage: USAGE}];
const saysThenAsks = (): MessageChunk[] => [{type: 'text', text: 'Checking. '}, ...ASK_FOR_TOOL];

// A hang fails in this long instead of stalling the suite; its tests stay on one line so a spec citation can name them.
const FAIL_FAST_MS = 2_000;

describe('the tool budget', () => {
  const warnings: Array<{category: string; message: string; fields?: Record<string, unknown>}> = [];

  beforeEach(() => {
    warnings.length = 0;
    const quiet = () => undefined;
    setLogger({
      debug: quiet,
      info: quiet,
      error: quiet,
      warn: (category, message, fields) => void warnings.push({category, message, fields}),
    });
  });

  afterEach(() => setLogger());

  it('executes 2 tool rounds and makes 3 provider calls at maxToolRounds 2', async () => {
    const {providerCalls, executions} = await budgetRun(2);

    expect({providerCalls, executions}).toEqual({providerCalls: 3, executions: 2});
  });

  it('executes 5 tool rounds and makes 6 provider calls at the default budget', async () => {
    const {providerCalls, executions} = await budgetRun();

    expect({providerCalls, executions}).toEqual({providerCalls: 6, executions: 5});
  });

  it('makes one provider call and executes no tool at maxToolRounds 0', async () => {
    const {providerCalls, executions} = await budgetRun(0);

    expect({providerCalls, executions}).toEqual({providerCalls: 1, executions: 0});
  });

  // prettier-ignore
  it('treats a negative budget as 0 and still terminates', async () => {
    const {providerCalls, executions} = await budgetRun(-3);

    expect({providerCalls, executions}).toEqual({providerCalls: 1, executions: 0});
  }, FAIL_FAST_MS);

  // prettier-ignore
  it('treats a NaN budget as the default and still terminates', async () => {
    const {providerCalls, executions} = await budgetRun(Number.NaN);

    expect({providerCalls, executions}).toEqual({providerCalls: 6, executions: 5});
  }, FAIL_FAST_MS);

  it('leaves a conversation that ends on its own unchanged, at the default and at 5', async () => {
    const atDefault = await budgetRun(undefined, toolThenFinish);
    const atFive = await budgetRun(5, toolThenFinish);

    expect([atDefault, atFive].map(({providerCalls, executions}) => ({providerCalls, executions}))).toEqual([
      {providerCalls: 2, executions: 1},
      {providerCalls: 2, executions: 1},
    ]);
  });

import {Ajv} from 'ajv';
import type {ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({allErrors: true});
  private readonly staticValidators = new Map<string, ValidateFunction>();
  private readonly dynamicValidatorCache = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private compileSchema(schema: Record<string, unknown>, toolName: string): ValidateFunction {
    try {
      return this.ajv.compile(schema);
    } catch (err) {
      throw new Error(`Tool '${toolName}' has an uncompilable inputSchema: ${(err as Error).message}`, {cause: err});
    }
  }

  private getValidator(name: string, tool: StoredTool): ValidateFunction {
    if (typeof tool.definitionSource !== 'function') {
      return this.staticValidators.get(name)!;
    }
    const definition = tool.definitionSource();
    const schema = definition.inputSchema;
    const cached = this.dynamicValidatorCache.get(schema);
    if (cached) return cached;
    const compiled = this.compileSchema(schema, name);
    this.dynamicValidatorCache.set(schema, compiled);
    return compiled;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    if (typeof definition !== 'function') {
      this.staticValidators.set(resolved.name, this.compileSchema(resolved.inputSchema, resolved.name));
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against the tool's inputSchema before execution; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }

    const validate = this.getValidator(name, tool);

    const valid = validate(input);
    if (!valid) {
      const errors = validate.errors ?? [];
      const message = errors.map(e => `${e.instancePath || '(root)'} ${e.message}`).join('; ');
      log.warn('tool', 'input validation failed', {name, paths: errors.map(e => e.instancePath)});
      return {result: `Tool '${name}' input invalid: ${message}`};
    }

    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
import type {OutgoingMessage} from './messages.js';

export interface TextMessage {
  role: 'user' | 'assistant';
  content: string;
}

export interface ToolCallContent {
  type: 'tool_use';
  toolUseId: string;
  name: string;
  input: Record<string, unknown>;
}

export interface ToolResultContent {
  type: 'tool_result';
  toolUseId: string;
  content: string;
}

export interface ToolUseMessage {
  role: 'assistant';
  content: ToolCallContent[];
}

export interface ToolResultMessage {
  role: 'user';
  content: ToolResultContent[];
}

export type Message = TextMessage | ToolUseMessage | ToolResultMessage;

export interface ToolDefinition {
  name: string;
  description: string;
  inputSchema: Record<string, unknown>;
  promptInstructions?: string;
  examplePrompts?: string[];
}

export interface ToolCall {
  id: string;
  name: string;
  input: Record<string, unknown>;
}

export type MessageChunk =
  | {type: 'text'; text: string}
  | {type: 'tool_use'; toolCall: ToolCall}
  | {type: 'tool_result'; clientMessages: OutgoingMessage[]}
  | {type: 'suppress_output'}
  | {type: 'stop'; stopReason: string; usage?: UsageMetadata};

export interface SendMessageParams {
  messages: Message[];
  systemPrompt: string;
  tools?: ToolDefinition[];
  maxTokens?: number;
}

export interface StructuredOutputParams<_T> {
  messages: Message[];
  systemPrompt: string;
  responseSchema: ResponseSchema;
  maxTokens?: number;
}

export interface ResponseSchema {
  type: 'object' | 'array' | 'string' | 'number' | 'boolean';
  properties?: Record<string, ResponseSchema>;
  items?: ResponseSchema;
  required?: string[];
  description?: string;
  enum?: string[];
}

export interface UsageMetadata {
  inputTokens: number;
  outputTokens: number;
  totalTokens: number;
}

export interface AIProviderResponse {
  usage?: UsageMetadata;
}

export interface AIProvider {
  sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk>;
  generateStructured<T>(params: StructuredOutputParams<T>): Promise<T>;
}

export class AIError extends Error {
  constructor(
    message: string,
    public readonly code: string,
    // eslint-disable-next-line re-lint/no-flag-params -- public API; splitting AIError is a breaking change (adrs/ADR-006-lint-suppressions.md)
    public readonly retryable: boolean = false
  ) {
    super(message);
    this.name = 'AIError';
  }
}
export interface PromptBuilderConfig {
  identity: string;
  domainContext?: string;
  responseGuidelines?: string;
  toolPreamble?: string;
}

export interface PromptBuilderOptions {
  toolInstructions?: string[];
  additionalContext?: string;
}

const DEFAULT_TOOL_PREAMBLE = `When users ask questions that relate to available tools, USE THE PROVIDED TOOLS to get accurate, real-time information.

IMPORTANT:
- Always use tools for specific data rather than guessing.
- If a tool call fails, explain the error and offer alternatives.
- Combine tool results with your knowledge to provide comprehensive answers.

CLARIFICATION RULE: If you are unsure which filter to apply or how to interpret the user's request, ASK the user for clarification BEFORE calling the tool.
When a question is clear and maps directly to known filters, proceed without asking.`;

export class PromptBuilder {
  constructor(private readonly config: PromptBuilderConfig) {}

  build(options: PromptBuilderOptions = {}): string {
    const {toolInstructions, additionalContext} = options;
    const parts: string[] = [this.config.identity];

    if (this.config.domainContext) {
      parts.push(this.config.domainContext);
    }

    if (toolInstructions?.length) {
      const preamble = this.config.toolPreamble ?? DEFAULT_TOOL_PREAMBLE;
      const numbered = toolInstructions.map((instruction, i) => `${i + 1}. ${instruction}`).join('\n\n');
      parts.push(`${preamble}\n\n${numbered}`);
    }

    if (this.config.responseGuidelines) {
      parts.push(`Response Guidelines:\n${this.config.responseGuidelines}`);
    }

    if (additionalContext) {
      parts.push(`Additional Context:\n${additionalContext}`);
    }

    return parts.join('\n\n');
  }
}

